            row_sums=[0]*n
            col_sums=[0]*n
            for i in range(n):
                for j in range(n):
                    k=i*n+j
                    v=(bits>>k)&1
                    row_sums[i]+=v
                    col_sums[j]+=v
            key=(tuple(row_sums), tuple(col_sums))
            groups[key].append(bits)
        ks=set()
        k_to_examples={}
        for key,lst in groups.items():
            if len(lst)==1:
                fixed=n*n
            else:
                and_bits=lst[0]
                or_bits=lst[0]
                for b in lst[1:]:
                    and_bits &= b
                    or_bits |= b
                mask=(1<<N)-1
                uniform_mask=(~(and_bits ^ or_bits)) & mask
                fixed=bin(uniform_mask).count('1')
            ks.add(fixed)
            if fixed not in k_to_examples:
                k_to_examples[fixed]=key
        lines.append(f"n={n} feasible ks sorted: {sorted(ks)}")
        lines.append(f"examples: {k_to_examples}")
        lines.append("")

    # alternative compute fixed via C1/C0 test
    def is_graphic(R,S):
        if sum(R)!=sum(S):
            return False
        Rs=sorted(R, reverse=True)
        Ss=sorted(S, reverse=True)
        m=len(Rs)
        n2=len(Ss)
        for v in Rs:
            if v<0 or v>n2: return False
        for v in Ss:
            if v<0 or v>m: return False
        prefix=0
        for k in range(1, n2+1):
            prefix += Ss[k-1]
            s = sum(min(ri, k) for ri in Rs)
            if prefix > s:
                return False
        return True

    for n in [2,3,4]:
        N=n*n
        groups=defaultdict(list)
        for bits in range(1 << N):
            row_sums=[0]*n
            col_sums=[0]*n
            for i in range(n):
                for j in range(n):
                    k=i*n+j
                    v=(bits>>k)&1
                    row_sums[i]+=v
                    col_sums[j]+=v
            key=(tuple(row_sums), tuple(col_sums))
            groups[key].append(bits)
        ks2=set()
        for key,lst in groups.items():
            R,S = key
            fixed=0
            for i in range(n):
                for j in range(n):
                    Ri=R[i]; Sj=S[j]
                    R1=list(R); S1=list(S)
                    R1[i]-=1; S1[j]-=1
                    c1=False
                    if R1[i]>=0 and S1[j]>=0:
                        c1=is_graphic(R1,S1)
                    Rc=[n - x for x in R]
                    Sc=[n - x for x in S]
                    Rc[i]-=1; Sc[j]-=1
                    c0=False
                    if Rc[i]>=0 and Sc[j]>=0 and Rc[i]<=n and Sc[j]<=n:
                        c0=is_graphic(Rc, Sc)
                    if c1 != c0:
                        fixed+=1
                    elif not c1 and not c0:
                        lines.append(f"both false {R},{S},{i},{j}")
                    else:
                        pass
            ks2.add(fixed)
        lines.append(f"n={n} ks via graphic test: {sorted(ks2)}")
    open("out.txt","w").write("\n".join(lines))
compute()
